  @IsEnum(SortOrder)
  order?: SortOrder = SortOrder.DESC;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(100)
  pageSize?: number = 10;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  page?: number = 1;

  @IsOptional()
  @IsString()
  q?: string;

  @IsOptional()
  @IsString()
  role?: string;

  @IsOptional()
  @Type(() => Date)
  lastContactedAt?: Date;

  get offset(): number {
    return ((this.page || 1) - 1) * (this.pageSize || 10);
  }

  // 计算 limit (take)
  get limit(): number {
    return this.pageSize || 10;
  }
}

