      await this.assertCompanyExists(dto.companyId);
    }

    if (dto.contactId !== undefined && dto.contactId !== null) {
      await this.assertContactBelongsToCompany(dto.contactId, resolvedCompanyId);
    }

    const mergedDeal = this.dealRepository.merge(currentDeal, {
