import { HttpStatus } from '@nestjs/common';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { DealStage } from './deal.entity';
import { DealService } from './deal.service';

describe('DealService', () => {
  const buildService = () => {
    const dealRepository = {
      create: jest.fn(),
      save: jest.fn(),
      findWithFilter: jest.fn(),
      findOne: jest.fn(),
      merge: jest.fn(),
      softDelete: jest.fn(),
    };

    const companyService = {
      getCompanyById: jest.fn(),
    };

    const contactService = {
      getContactById: jest.fn(),
    };

    const service = new DealService(
      dealRepository as any,
      companyService as any,
      contactService as any,
    );

    return {
      service,
      dealRepository,
      companyService,
      contactService,
    };
  };

  it('creates a deal and defaults stage to lead', async () => {
    const { service, dealRepository, companyService } = buildService();

    companyService.getCompanyById.mockResolvedValue({ id: 'company-1' });
    dealRepository.create.mockImplementation((payload) => payload);
    dealRepository.save.mockImplementation(async (payload) => ({
      id: 'deal-1',
      ...payload,
    }));

    const created = await service.createDeal({
      name: 'Pilot Expansion',
      value: 12500,
      companyId: 'company-1',
    });

    expect(created.stage).toBe(DealStage.LEAD);
    expect(created.contactId).toBeNull();
    expect(created.expectedCloseDate).toBeNull();
    expect(Number(created.value)).toBe(12500);
  });

  it('returns parent-not-found when company does not exist', async () => {
    const { service, companyService } = buildService();

    companyService.getCompanyById.mockRejectedValue(
      new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: 'Company not found',
      }),
    );

    await expect(
      service.createDeal({
        name: 'Missing Parent',
        value: 200,
        companyId: 'missing-company',
      }),
    ).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
      },
    });
  });

  it('returns parent-not-found when contact does not exist', async () => {
    const { service, companyService, contactService } = buildService();

    companyService.getCompanyById.mockResolvedValue({ id: 'company-1' });
    contactService.getContactById.mockRejectedValue(
      new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: 'Contact not found',
      }),
    );

    await expect(
      service.createDeal({
        name: 'Missing Contact',
        value: 300,
        companyId: 'company-1',
        contactId: 'missing-contact',
      }),
    ).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
      },
    });
  });

  it('returns paginated list from repository with stage/company filters', async () => {
    const { service, dealRepository } = buildService();

    const expected = {
      items: [{ id: 'deal-1' }],
      total: 1,
      page: 1,
      pageSize: 10,
      totalPages: 1,
    };

    dealRepository.findWithFilter.mockResolvedValue(expected);

    const result = await service.getDealsList({
      page: 1,
      pageSize: 10,
      stage: 'proposal',
      companyId: 'company-1',
    });

    expect(dealRepository.findWithFilter).toHaveBeenCalledWith({
      page: 1,
      pageSize: 10,
      stage: 'proposal',
      companyId: 'company-1',
    });
    expect(result).toEqual(expected);
  });

  it('returns deal detail with linked company summary', async () => {
    const { service, dealRepository, companyService } = buildService();

    dealRepository.findOne.mockResolvedValue({
      id: 'deal-1',
      name: 'Detail Deal',
      value: '500.00',
      companyId: 'company-1',
      stage: DealStage.QUALIFIED,
    });
    companyService.getCompanyById.mockResolvedValue({
      id: 'company-1',
      name: 'Acme Corp',
      status: '1',
    });

    const result = await service.getDealWithCompany('deal-1');

    expect(result.company).toEqual({
      id: 'company-1',
      name: 'Acme Corp',
      status: '1',
    });
  });

  it('returns entity-not-found for missing deal id', async () => {
    const { service, dealRepository } = buildService();

    dealRepository.findOne.mockResolvedValue(null);

    await expect(service.getDealById('missing-deal')).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
      },
    });
  });

  it('updates with subset fields and rejects empty payload', async () => {
    const { service, dealRepository, companyService } = buildService();

    const existing = {
      id: 'deal-1',
      name: 'Original',
      value: '100.00',
      stage: DealStage.LEAD,
      companyId: 'company-1',
      contactId: 'contact-1',
      expectedCloseDate: new Date('2026-01-01T00:00:00.000Z'),
    };

    dealRepository.findOne.mockResolvedValue(existing);
    dealRepository.merge.mockImplementation((current, payload) => ({
      ...current,
      ...payload,
    }));
    dealRepository.save.mockImplementation(async (payload) => payload);
    companyService.getCompanyById.mockResolvedValue({ id: 'company-1' });

    const updated = await service.updateDeal('deal-1', {
      stage: DealStage.CLOSED_WON,
      value: 200,
      contactId: null,
      expectedCloseDate: null,
    });

    expect(updated.stage).toBe(DealStage.CLOSED_WON);
    expect(Number(updated.value)).toBe(200);
    expect(updated.contactId).toBeNull();
    expect(updated.expectedCloseDate).toBeNull();

    await expect(service.updateDeal('deal-1', {})).rejects.toMatchObject({
      status: HttpStatus.BAD_REQUEST,
      response: {
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
      },
    });
  });
});

