import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { ContactService } from '../contact/contact.service';
import { CompanyService } from '../company/company.service';
import { CreateDealDto, DealListQueryDto, UpdateDealDto } from './dto';
import { DealEntity, DealStage } from './deal.entity';
import { DealRepository } from './deal.repository';

@Injectable()
export class DealService {
  constructor(
    private readonly dealRepository: DealRepository,
    private readonly companyService: CompanyService,
    private readonly contactService: ContactService,
  ) {}

  async createDeal(dto: CreateDealDto): Promise<DealEntity> {
    await this.assertCompanyExists(dto.companyId);

    if (dto.contactId) {
      await this.assertContactBelongsToCompany(dto.contactId, dto.companyId);
    }

    const deal = this.dealRepository.create({
      ...dto,
      stage: dto.stage ?? DealStage.LEAD,
      value: dto.value.toFixed(2),
      contactId: dto.contactId ?? null,
      expectedCloseDate: dto.expectedCloseDate ?? null,
    });

    return this.dealRepository.save(deal);
  }

  async getDealsList(query: DealListQueryDto) {
    return this.dealRepository.findWithFilter(query);
  }

  async getDealById(id: string): Promise<DealEntity> {
    const deal = await this.dealRepository.findOne({ where: { id } });

    if (!deal) {
      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: `Deal with ID ${id} not found`,
        details: {
          resource: 'Deal',
          id,
        },
      });
    }

    return deal;
  }

  async getDealWithCompany(id: string) {
    const deal = await this.getDealById(id);
    const company = await this.companyService.getCompanyById(deal.companyId);

    return {
      ...deal,
      company: {
        id: company.id,
        name: company.name,
        status: company.status,
      },
    };
  }

  async updateDeal(id: string, dto: UpdateDealDto): Promise<DealEntity> {
    if (Object.keys(dto).length === 0) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'Request body must include at least one field to update.',
        details: {
          errors: [
            {
              field: 'body',
              messages: ['Request body must include at least one field to update.'],
            },
          ],
        },
      });
    }

    const currentDeal = await this.getDealById(id);
    const resolvedCompanyId = dto.companyId ?? currentDeal.companyId;

    if (dto.companyId && dto.companyId !== currentDeal.companyId) {
      await this.assertCompanyExists(dto.companyId);
    }

    if (dto.contactId !== undefined && dto.contactId !== null) {
      await this.assertContactBelongsToCompany(dto.contactId, resolvedCompanyId);
    }

    const mergedDeal = this.dealRepository.merge(currentDeal, {
      ...dto,
      value: dto.value === undefined ? currentDeal.value : dto.value.toFixed(2),
      contactId: dto.contactId === undefined ? currentDeal.contactId : dto.contactId,
      expectedCloseDate:
        dto.expectedCloseDate === undefined
          ? currentDeal.expectedCloseDate
          : dto.expectedCloseDate,
    });

    return this.dealRepository.save(mergedDeal);
  }

  async removeDeal(id: string): Promise<void> {
    await this.getDealById(id);
    await this.dealRepository.softDelete(id);
  }

  private async assertCompanyExists(companyId: string) {
    try {
      await this.companyService.getCompanyById(companyId);
    } catch (error) {
      if (!(error instanceof HttpException) || error.getStatus() !== 404) {
        throw error;
      }

      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
        message: `Company with ID ${companyId} not found`,
        details: {
          resource: 'Company',
          id: companyId,
        },
      });
    }
  }

  private async assertContactBelongsToCompany(
    contactId: string,
    companyId: string,
  ) {
    const contact = await this.assertContactExists(contactId);

    if (contact.companyId !== companyId) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'Selected contact must belong to the selected company.',
        details: {
          errors: [
            {
              field: 'contactId',
              messages: ['Selected contact must belong to the selected company.'],
            },
          ],
        },
      });
    }
  }

  private async assertContactExists(contactId: string) {
    try {
      return await this.contactService.getContactById(contactId);
    } catch (error) {
      if (!(error instanceof HttpException) || error.getStatus() !== 404) {
        throw error;
      }

      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
        message: `Contact with ID ${contactId} not found`,
        details: {
          resource: 'Contact',
          id: contactId,
        },
      });
    }
  }
}
