import {
  useCreateDeal,
  useDealList,
  useDeleteDeal,
  useUpdateDeal,
} from './dealQueries';

function extractErrorMessage(error, fallbackMessage) {
  return error?.message || fallbackMessage;
}

export default function DealsPage() {
  const navigate = useNavigate();
  const createDeal = useCreateDeal();
  const updateDeal = useUpdateDeal();
  const deleteDeal = useDeleteDeal();

  const [formState, setFormState] = useState({ open: false, mode: 'create', deal: null });
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [feedback, setFeedback] = useState({ open: false, severity: 'success', message: '' });
  const [searchInput, setSearchInput] = useState('');
  const [listQuery, setListQuery] = useState({
    page: 1,
    pageSize: 10,
    stage: undefined,
    companyId: undefined,
  });

  const dealsQuery = useDealList(listQuery);
  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });

  const handleFormSubmit = async (payload) => {
    try {
      if (formState.mode === 'create') {
        await createDeal.mutateAsync(payload);
        setFeedback({ open: true, severity: 'success', message: 'Deal created.' });
      } else {
        await updateDeal.mutateAsync({
          id: formState.deal.id,
          data: payload,
        });
        setFeedback({ open: true, severity: 'success', message: 'Deal updated.' });
      }

      setFormState({ open: false, mode: 'create', deal: null });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Deal request failed.'),
        });
      }
    }
  };

  const handleDelete = async () => {
    if (!deleteTarget) {
      return;
    }

    try {
      await deleteDeal.mutateAsync(deleteTarget.id);
      setDeleteTarget(null);
      setFeedback({
        open: true,
        severity: 'success',
        message: 'Deal deleted.',
      });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Delete failed.'),
        });
      }
    }
  };

  const handlePageChange = (page) => {
    setListQuery((current) => ({ ...current, page }));
  };

  const handlePageSizeChange = (pageSize) => {
    setListQuery((current) => ({ ...current, page: 1, pageSize }));
  };

  const handleFilterChange = (field) => (event) => {
    const value = event.target.value;

    setListQuery((current) => ({
      ...current,
      page: 1,
      [field]: value || undefined,
    }));
  };

  const handleResetFilters = () => {
    setSearchInput('');
    setListQuery((current) => ({
      page: 1,
      pageSize: current.pageSize,
      stage: undefined,
      companyId: undefined,
    }));
  };

  const dealPage = dealsQuery.data;
  const dealItems = dealPage?.items ?? [];

  return (
    <Stack spacing={3}>
      <DataTableShell
        title="Deals"
        searchValue={searchInput}
        onSearchChange={setSearchInput}
        onSearchSubmit={(event) => event.preventDefault()}
        onReset={handleResetFilters}
        searchPlaceholder="Filtering is available by stage and company"
        filters={(
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5}>
            <TextField
              select
              size="small"
              label="Stage"
              value={listQuery.stage ?? ''}
              onChange={handleFilterChange('stage')}
              sx={{ minWidth: '11rem' }}
            >
              <MenuItem value="">All stages</MenuItem>
              <MenuItem value="lead">Lead</MenuItem>
              <MenuItem value="qualified">Qualified</MenuItem>
              <MenuItem value="proposal">Proposal</MenuItem>
              <MenuItem value="negotiation">Negotiation</MenuItem>
              <MenuItem value="closed_won">Closed Won</MenuItem>
              <MenuItem value="closed_lost">Closed Lost</MenuItem>
            </TextField>

            <TextField
              select
              size="small"
              label="Company"
              value={listQuery.companyId ?? ''}
              onChange={handleFilterChange('companyId')}
              sx={{ minWidth: '14rem' }}
            >
              <MenuItem value="">All companies</MenuItem>
              {(companiesQuery.data?.items ?? []).map((company) => (
                <MenuItem key={company.id} value={company.id}>
                  {company.name}
                </MenuItem>
              ))}
            </TextField>
          </Stack>
        )}
        actions={(
          <Button
            variant="contained"
            startIcon={<PlusOutlined />}
            onClick={() =>
              setFormState({
                open: true,
                mode: 'create',
                deal: null,
              })
            }
          >
            Add Deal
          </Button>
        )}
        loading={dealsQuery.isLoading}
        error={
          dealsQuery.isError && !isTransportError(dealsQuery.error)
            ? extractErrorMessage(dealsQuery.error, 'Failed to load deals.')
            : null
        }
        isEmpty={!dealsQuery.isLoading && !dealsQuery.isError && dealItems.length === 0}
        emptyTitle="No matching deals"
        emptyDescription="Try selecting a different stage or company filter."
        pagination={
          dealPage && dealPage.total >= 0 ? (
            <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
              <DataTablePagination
                page={dealPage.page}
                pageSize={dealPage.pageSize}
                total={dealPage.total}
                totalPages={dealPage.totalPages}
                onPageChange={handlePageChange}
                onPageSizeChange={handlePageSizeChange}
              />
            </Box>
          ) : null
        }
      >
        <DealTable
          deals={dealItems}
          onDelete={setDeleteTarget}
          onEdit={(deal) => setFormState({ open: true, mode: 'edit', deal })}
          onView={(deal) => navigate(`/deals/${deal.id}`)}
        />
      </DataTableShell>

      <DealFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.deal}
        isPending={createDeal.isPending || updateDeal.isPending}
        onClose={() => setFormState({ open: false, mode: 'create', deal: null })}
        onSubmit={handleFormSubmit}
      />

      <Dialog open={Boolean(deleteTarget)} onClose={() => setDeleteTarget(null)}>
        <DialogTitle>Delete deal</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to delete <strong>{deleteTarget?.name}</strong>?
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteTarget(null)}>Cancel</Button>
          <Button
            variant="contained"
            color="error"
            onClick={handleDelete}
            disabled={deleteDeal.isPending}
          >
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={feedback.open}
        autoHideDuration={4000}
        onClose={() => setFeedback((current) => ({ ...current, open: false }))}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert
          severity={feedback.severity}
          variant="filled"
          onClose={() => setFeedback((current) => ({ ...current, open: false }))}
        >
          {feedback.message}
        </Alert>
      </Snackbar>
    </Stack>
  );
}
import {
  Alert,
  Autocomplete,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  MenuItem,
  Stack,
  TextField,
} from '@mui/material';
import { useEffect, useMemo, useState } from 'react';

import { useCompanyList } from '../companies/companyQueries';
import { useContactList } from '../contacts/contactQueries';

const STAGE_OPTIONS = [
  { value: 'lead', label: 'Lead' },
  { value: 'qualified', label: 'Qualified' },
  { value: 'proposal', label: 'Proposal' },
  { value: 'negotiation', label: 'Negotiation' },
  { value: 'closed_won', label: 'Closed Won' },
  { value: 'closed_lost', label: 'Closed Lost' },
];

function formatDateTimeLocal(value) {
  if (!value) {
    return '';
  }

  const date = new Date(value);
  const timezoneOffset = date.getTimezoneOffset() * 60000;
  return new Date(date.getTime() - timezoneOffset).toISOString().slice(0, 16);
}

function normalizeInitialValues(initialValues) {
  return {
    name: initialValues?.name ?? '',
    value: initialValues?.value ?? '',
    stage: initialValues?.stage ?? 'lead',
    companyId: initialValues?.companyId ?? '',
    contactId: initialValues?.contactId ?? '',
    expectedCloseDate: formatDateTimeLocal(initialValues?.expectedCloseDate),
  };
}

function validate(values) {
  const errors = {};

  if (!values.name.trim()) {
    errors.name = 'Name is required.';
  }

  if (values.value === '' || values.value === null || values.value === undefined) {
    errors.value = 'Value is required.';
  } else if (Number(values.value) < 0) {
    errors.value = 'Value must be non-negative.';
  }

  if (!values.companyId) {
    errors.companyId = 'Company is required.';
  }

  return errors;
}

export function DealFormDialog({
  open,
  mode,
  initialValues,
  onClose,
  onSubmit,
  isPending,
}) {
  const [values, setValues] = useState(normalizeInitialValues(initialValues));
  const [errors, setErrors] = useState({});
  const [touched, setTouched] = useState({});

  useEffect(() => {
    if (open) {
      setValues(normalizeInitialValues(initialValues));
      setErrors({});
      setTouched({});
    }
  }, [open, initialValues]);

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const contactsQuery = useContactList(
    values.companyId ? { companyId: values.companyId, page: 1, pageSize: 100 } : { page: 1, pageSize: 100 },
  );

  const companyOptions = companiesQuery.data?.items ?? [];
  const contactOptions = useMemo(() => {
    const list = contactsQuery.data?.items ?? [];

    if (!values.companyId) {
      return [];
    }

    return list.filter((contact) => contact.companyId === values.companyId);
  }, [contactsQuery.data?.items, values.companyId]);

  useEffect(() => {
    if (!values.companyId) {
      setValues((current) => ({ ...current, contactId: '' }));
      return;
    }

    if (values.contactId && !contactOptions.some((contact) => contact.id === values.contactId)) {
      setValues((current) => ({ ...current, contactId: '' }));
    }
  }, [values.companyId, values.contactId, contactOptions]);

  const companyValue =
    companyOptions.find((option) => option.id === values.companyId) ?? null;
  const contactValue =
    contactOptions.find((option) => option.id === values.contactId) ?? null;

  const handleFieldChange = (field) => (event) => {
    const fieldValue = event.target.value;
    setValues((current) => ({ ...current, [field]: fieldValue }));

    if (errors[field]) {
      setErrors((current) => {
        const next = { ...current };
        delete next[field];
        return next;
      });
    }
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
    const nextErrors = validate(values);
    setErrors(nextErrors);
  };

  const handleSubmit = async (event) => {
    event?.preventDefault();

    const nextErrors = validate(values);
    setErrors(nextErrors);
    setTouched({
      name: true,
      value: true,
      companyId: true,
    });

    if (Object.keys(nextErrors).length > 0) {
      return;
    }

    const payload = {
      name: values.name.trim(),
      value: Number(values.value),
      stage: values.stage || undefined,
      companyId: values.companyId,
      contactId: values.contactId || null,
      expectedCloseDate: values.expectedCloseDate
        ? new Date(values.expectedCloseDate).toISOString()
        : null,
    };

    await onSubmit(payload);
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>{mode === 'create' ? 'Create deal' : 'Edit deal'}</DialogTitle>

      <DialogContent className="!p-5">
        <Stack direction="column" spacing={2} component="form" onSubmit={handleSubmit} sx={{ mt: 1 }}>
          <TextField
            required
            fullWidth
            label="Name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleFieldChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
              fullWidth
              label="Value"
              type="number"
              value={values.value}
              onBlur={handleBlur('value')}
              onChange={handleFieldChange('value')}
              error={touched.value && Boolean(errors.value)}
              helperText={touched.value ? errors.value : undefined}
              inputProps={{ min: 0, step: '0.01' }}
            />

            <TextField
              select
              fullWidth
              label="Stage"
              value={values.stage}
              onChange={handleFieldChange('stage')}
            >
              {STAGE_OPTIONS.map((option) => (
                <MenuItem key={option.value} value={option.value}>
                  {option.label}
                </MenuItem>
              ))}
            </TextField>
          </Stack>

          <Autocomplete
            options={companyOptions}
            loading={companiesQuery.isLoading}
            value={companyValue}
            onChange={(_, selectedCompany) => {
              setValues((current) => ({
                ...current,
                companyId: selectedCompany?.id ?? '',
                contactId: '',
              }));
              setTouched((current) => ({ ...current, companyId: true }));
            }}
            getOptionLabel={(option) => option?.name ?? ''}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Company"
                error={touched.companyId && Boolean(errors.companyId)}
                helperText={
                  touched.companyId
                    ? errors.companyId
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? <CircularProgress color="inherit" size={20} /> : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <Autocomplete
            options={contactOptions}
            loading={contactsQuery.isLoading}
            disabled={!values.companyId}
            value={contactValue}
            onChange={(_, selectedContact) => {
              setValues((current) => ({
                ...current,
                contactId: selectedContact?.id ?? '',
              }));
            }}
            getOptionLabel={(option) => option?.name ?? ''}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            renderInput={(params) => (
              <TextField
                {...params}
                label="Contact (optional)"
                helperText={
                  !values.companyId
                    ? 'Select a company first.'
                    : contactsQuery.isError
                      ? 'Failed to load contacts.'
                      : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {contactsQuery.isLoading ? <CircularProgress color="inherit" size={20} /> : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <TextField
            fullWidth
            label="Expected Close Date"
            type="datetime-local"
            InputLabelProps={{ shrink: true }}
            value={values.expectedCloseDate}
            onChange={handleFieldChange('expectedCloseDate')}
          />

          {mode === 'edit' && initialValues?.createdAt ? (
            <TextField
              disabled
              label="Created At"
              value={new Intl.DateTimeFormat('en', {
                dateStyle: 'medium',
                timeStyle: 'short',
              }).format(new Date(initialValues.createdAt))}
            />
          ) : null}

          {contactsQuery.isError ? (
            <Alert severity="warning">Contacts could not be loaded; you can still save without a contact.</Alert>
          ) : null}

          <button type="submit" hidden />
        </Stack>
      </DialogContent>

      <DialogActions className="crm-dialog-actions">
        <Button onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button variant="contained" onClick={handleSubmit} disabled={isPending}>
          {mode === 'create' ? 'Create' : 'Save'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}
import {
  Button,
  Chip,
  IconButton,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from '@mui/material';
import DeleteOutlined from '@ant-design/icons/DeleteOutlined';
import EditOutlined from '@ant-design/icons/EditOutlined';
import EyeOutlined from '@ant-design/icons/EyeOutlined';

function formatDate(value) {
  if (!value) {
    return '—';
  }

  return new Intl.DateTimeFormat('en', {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(new Date(value));
}

function formatValue(value) {
  const amount = Number(value ?? 0);

  return Number.isFinite(amount)
    ? amount.toLocaleString('en-US', {
        style: 'currency',
        currency: 'USD',
        maximumFractionDigits: 2,
      })
    : '—';
}

function stageColor(stage) {
  const colorMap = {
    lead: 'default',
    qualified: 'info',
    proposal: 'warning',
    negotiation: 'secondary',
    closed_won: 'success',
    closed_lost: 'error',
  };

  return colorMap[stage] ?? 'default';
}

function stageLabel(stage) {
  if (!stage) {
    return '—';
  }

  return stage.replaceAll('_', ' ').replace(/\b\w/g, (char) => char.toUpperCase());
}

function ActionCell({ deal, onView, onEdit, onDelete }) {
  return (
    <TableCell align="right">
      <Stack direction="row" spacing={1} justifyContent="flex-end">
        <Button
          size="small"
          startIcon={<EyeOutlined />}
          onClick={() => onView(deal)}
        >
          View
        </Button>
        <IconButton onClick={() => onEdit(deal)} aria-label="edit">
          <EditOutlined />
        </IconButton>
        <IconButton color="error" onClick={() => onDelete(deal)} aria-label="delete">
          <DeleteOutlined />
        </IconButton>
      </Stack>
    </TableCell>
  );
}

export function DealTable({ deals, onView, onDelete, onEdit }) {
  return (
    <TableContainer component={Paper} className="crm-table-shell">
      <Table size="small">
        <TableHead>
          <TableRow>
            <TableCell>Deal</TableCell>
            <TableCell>Company</TableCell>
            <TableCell>Contact</TableCell>
            <TableCell>Value</TableCell>
            <TableCell>Stage</TableCell>
            <TableCell>Expected Close</TableCell>
            <TableCell>Created</TableCell>
            <TableCell align="right">Actions</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {deals.map((deal) => (
            <TableRow key={deal.id} hover>
              <TableCell>{deal.name}</TableCell>
              <TableCell>{deal.company?.name || deal.companyId}</TableCell>
              <TableCell>{deal.contact?.name || '—'}</TableCell>
              <TableCell>{formatValue(deal.value)}</TableCell>
              <TableCell>
                <Chip size="small" color={stageColor(deal.stage)} label={stageLabel(deal.stage)} />
              </TableCell>
              <TableCell>{formatDate(deal.expectedCloseDate)}</TableCell>
              <TableCell>{formatDate(deal.createdAt)}</TableCell>

              <ActionCell
                deal={deal}
                onView={onView}
                onEdit={onEdit}
                onDelete={onDelete}
              />
            </TableRow>
