            <DetailRow label="Company" value={deal.company?.name || deal.companyId} />
            <DetailRow label="Contact" value={deal.contact?.name || deal.contactId || '—'} />
            <DetailRow label="Value" value={formatValue(deal.value)} />
            <DetailRow
              label="Stage"
