                DealStage.NEGOTIATION,
                DealStage.CLOSED_WON,
              ][companyIndex % 4],
              contactId: companyContacts[0].id,
              expectedCloseDate:
                companyIndex % 5 === 0
                  ? null
                  : distributeRecentDate(now, companyIndex, 35),
            }),
          ),
        );
      }
    }

    return {
      scenario: 'edge-case',
      companiesCreated: savedCompanies.length,
      contactsCreated,
      dealsCreated,
      notes: [
        'Includes one company with zero contacts for empty-state testing.',
        'Creates 25 companies to exercise pagination and sorting.',
        'Adds null fields and max-length values for company/contact/deal edge cases.',
      ],
    };
  },
};
