      merge: jest.fn(),
      softDelete: jest.fn(),
    };

    const companyService = {
      getCompanyById: jest.fn(),
    };

    const contactService = {
      getContactById: jest.fn(),
    };

    const service = new DealService(
      dealRepository as any,
      companyService as any,
      contactService as any,
    );

    return {
      service,
      dealRepository,
      companyService,
      contactService,
    };
  };

  it('creates a deal and defaults stage to lead', async () => {
    const { service, dealRepository, companyService } = buildService();

    companyService.getCompanyById.mockResolvedValue({ id: 'company-1' });
    dealRepository.create.mockImplementation((payload) => payload);
    dealRepository.save.mockImplementation(async (payload) => ({
      id: 'deal-1',
      ...payload,
    }));

    const created = await service.createDeal({
      name: 'Pilot Expansion',
      value: 12500,
      companyId: 'company-1',
    });

    expect(created.stage).toBe(DealStage.LEAD);
    expect(created.contactId).toBeNull();
    expect(created.expectedCloseDate).toBeNull();
    expect(Number(created.value)).toBe(12500);
  });

  it('returns parent-not-found when company does not exist', async () => {
    const { service, companyService } = buildService();

    companyService.getCompanyById.mockRejectedValue(
      new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: 'Company not found',
      }),
    );

    await expect(
      service.createDeal({
        name: 'Missing Parent',
        value: 200,
        companyId: 'missing-company',
      }),
    ).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
      },
    });
  });

  it('returns parent-not-found when contact does not exist', async () => {
    const { service, companyService, contactService } = buildService();

    companyService.getCompanyById.mockResolvedValue({ id: 'company-1' });
