      new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: 'Contact not found',
      }),
    );

    await expect(
      service.createDeal({
        name: 'Missing Contact',
        value: 300,
        companyId: 'company-1',
        contactId: 'missing-contact',
      }),
