import { Injectable } from '@nestjs/common';
import { DataSource, FindOptionsWhere } from 'typeorm';
import { BaseRepository } from '../../core/database/base.repository';
import { DealEntity, DealStage } from './deal.entity';
import { DealListQueryDto } from './dto';

type DealContactRow = {
  dealId: string;
  contactId: string;
  role: string | null;
  contactName: string;
};

@Injectable()
export class DealRepository extends BaseRepository<DealEntity> {
  constructor(private dataSource: DataSource) {
    super(DealEntity, dataSource.createEntityManager());
  }

  async findWithFilter(query: DealListQueryDto) {
    const where: FindOptionsWhere<DealEntity> = {};

    if (query.stage) {
      where.stage = query.stage as DealStage;
    }

    if (query.companyId) {
      where.companyId = query.companyId;
    }

    return this.paginate(query.page ?? 1, query.pageSize ?? 10, {
      where,
      order: { createdAt: 'DESC' },
    });
  }

  async getContactRowsForDeals(dealIds: string[]) {
    if (dealIds.length === 0) {
      return [];
    }

    return this.dataSource.query(
      "'`
      SELECT
        dc."dealId" as "dealId",
        dc."contactId" as "contactId",
