            resource: '"'Company',
            id: companyId,
          },
        });
      }

      throw error;
    }
  }

  private async assertCompaniesExist(companyIds: string[]) {
    for (const companyId of companyIds) {
      await this.assertCompanyExists(companyId);
    }
  }

  private async hydrateSingleContact(contact: ContactEntity): Promise<HydratedContact> {
    const [hydrated] = await this.hydrateContacts([contact]);
    return hydrated;
  }

  private async hydrateContacts(contacts: ContactEntity[]): Promise<HydratedContact[]> {
    if (contacts.length === 0) {
      return [];
    }

    const rows = await this.contactRepository.getCompanyRowsForContacts(
      contacts.map((contact) => contact.id),
    );

    const companiesByContactId = new Map<
      string,
      Array<{ id: string; name: string; primary: boolean }>
    >();

    for (const row of rows) {
      const current = companiesByContactId.get(row.contactId) ?? [];
      current.push({
        id: row.companyId,
        name: row.companyName,
        primary: row.isPrimary === true || row.isPrimary === 'true',
      });
      companiesByContactId.set(row.contactId, current);
    }

    return contacts.map((contact) => ({
      ...contact,
      companies: companiesByContactId.get(contact.id) ?? [],
    }));
  }
}
