    )) as Array<{ contactId: string }>;

    const validContactIds = new Set(rows.map((row) => row.contactId));
    const invalidContactId = contactIds.find((contactId) => !validContactIds.has(contactId));

    if (invalidContactId) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: '"'Selected contacts must be linked to the selected company.',
        details: {
          errors: [
            {
              field: 'contactLinks',
              messages: ['Selected contacts must be linked to the selected company.'],
            },
          ],
        },
      });
    }
  }

  private resolveCompanyLinksFromDto(
    dto: Pick<CreateContactDto, 'companyId' | 'companyLinks'>,
  ) {
    if (dto.companyLinks && dto.companyLinks.length > 0) {
      return dto.companyLinks;
    }

    if (dto.companyId) {
      return [{ companyId: dto.companyId, primary: true }];
    }

    return [];
  }

  private validateCompanyLinks(companyLinks: ContactCompanyLinkDto[]) {
    if (companyLinks.length === 0) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'At least one company link is required.',
      });
    }

    const primaryCount = companyLinks.filter((link) => link.primary).length;

    if (primaryCount "'!== 1) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: '"'Exactly one primary company link is required.',
      });
    }

    const seen = new Set<string>();

    for (const link of companyLinks) {
      if (seen.has(link.companyId)) {
        throw new AppException({
          statusCode: HttpStatus.BAD_REQUEST,
          code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
          message: 'Duplicate company link detected.',
          details: {
            errors: [
              {
                field: 'companyLinks',
                messages: ['Each company may be linked only once.'],
              },
            ],
          },
        });
      }

      seen.add(link.companyId);
    }
  }

  private async assertCompanyExists(companyId: string) {
    try {
      await this.companyService.getCompanyById(companyId);
    } catch (error) {
      if (error instanceof HttpException && error.getStatus() === 404) {
        throw new AppException({
          statusCode: HttpStatus.NOT_FOUND,
          code: BUSINESS_ERROR_CODES.NOT_FOUND,
          message: "'`Company with ID ${companyId} not found`,
          details: {
            resource: '"'Company',
            id: companyId,
          },
        });
      }

      throw error;
    }
  }

  private async assertCompaniesExist(companyIds: string[]) {
    for (const companyId of companyIds) {
      await this.assertCompanyExists(companyId);
    }
  }

  private async hydrateSingleContact(contact: ContactEntity): Promise<HydratedContact> {
    const [hydrated] = await this.hydrateContacts([contact]);
    return hydrated;
  }

  private async hydrateContacts(contacts: ContactEntity[]): Promise<HydratedContact[]> {
    if (contacts.length === 0) {
      return [];
    }

    const rows = await this.contactRepository.getCompanyRowsForContacts(
      contacts.map((contact) => contact.id),
    );

    const companiesByContactId = new Map<
      string,
      Array<{ id: string; name: string; primary: boolean }>
    >();

    for (const row of rows) {
      const current = companiesByContactId.get(row.contactId) ?? [];
      current.push({
        id: row.companyId,
        name: row.companyName,
        primary: row.isPrimary === true || row.isPrimary === 'true',
      });
      companiesByContactId.set(row.contactId, current);
    }

    return contacts.map((contact) => ({
      ...contact,
      companies: companiesByContactId.get(contact.id) ?? [],
    }));
  }
}
