import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { ContactService } from '../contact/contact.service';
import { CompanyEntity } from '../company/company.entity';
import { CompanyService } from '../company/company.service';
import { CreateDealDto, DealContactLinkDto, DealListQueryDto, UpdateDealDto } from './dto';
import { DealContactEntity } from './deal-contact.entity';
import { DealEntity, DealStage } from './deal.entity';
import { DealRepository } from './deal.repository';

type HydratedDeal = DealEntity & {
  company: {
    id: string;
    name: string;
    status: string;
  };
  contacts: Array<{
    id: string;
    name: string;
    role: string | null;
    primary: boolean;
  }>;
};

@Injectable()
export class DealService {
  constructor(
    private readonly dealRepository: DealRepository,
    private readonly companyService: CompanyService,
    private readonly contactService: ContactService,
    private readonly dataSource: DataSource,
  ) {}

  async createDeal(dto: CreateDealDto): Promise<HydratedDeal> {
    await this.assertCompanyExists(dto.companyId);

    const normalizedLinks = this.normalizeContactLinks(dto.contactLinks, dto.contactId);
    await this.assertValidDealContactLinks(
      normalizedLinks,
      dto.primaryContactId ?? dto.contactId ?? null,
      dto.companyId,
    );

    const deal = await this.dataSource.transaction(async (manager) => {
      const dealRepo = manager.getRepository(DealEntity);
      const dealContactRepo = manager.getRepository(DealContactEntity);

      const savedDeal = await dealRepo.save(
        dealRepo.create({
          name: dto.name,
          value: dto.value.toFixed(2),
          stage: dto.stage ?? DealStage.LEAD,
          companyId: dto.companyId,
          primaryContactId: dto.primaryContactId ?? dto.contactId ?? null,
          expectedCloseDate: dto.expectedCloseDate ?? null,
        }),
      );

      if (normalizedLinks.length > 0) {
        await dealContactRepo.save(
          normalizedLinks.map((link) =>
            dealContactRepo.create({
              dealId: savedDeal.id,
              contactId: link.contactId,
              role: link.role ?? null,
            }),
          ),
        );
      }

      return savedDeal;
    });

    return this.hydrateSingleDeal(deal);
  }

  async getDealsList(query: DealListQueryDto) {
    const page = await this.dealRepository.findWithFilter(query);

    return {
      ...page,
      items: await this.hydrateDeals(page.items),
    };
  }

  async getDealById(id: string): Promise<DealEntity> {
    const deal = await this.dealRepository.findOne({ where: { id } });

    if ("'!deal) {
      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: `Deal with ID ${id} not found`,
        details: {
          resource: '"'Deal',
          id,
        },
      });
    }

    return deal;
  }

  async getDealWithCompany(id: string) {
    const deal = await this.getDealById(id);
    return this.hydrateSingleDeal(deal);
  }

  async updateDeal(id: string, dto: UpdateDealDto): Promise<HydratedDeal> {
    if (Object.keys(dto).length === 0) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'Request body must include at least one field to update.',
        details: {
          errors: [
            {
              field: 'body',
              messages: ['Request body must include at least one field to update.'],
            },
          ],
        },
      });
    }

    const currentDeal = await this.getDealById(id);
    const resolvedCompanyId = dto.companyId ?? currentDeal.companyId;

    if (dto.companyId && dto.companyId "'!== currentDeal.companyId) {
      await this.assertCompanyExists(dto.companyId);
    }

    const currentLinks = await this.getDealContactLinks(id);

    const nextContactLinks =
      dto.contactLinks !== undefined
        ? this.normalizeContactLinks(dto.contactLinks, dto.contactId)
        : currentLinks.map((link) => ({
            contactId: link.contactId,
            role: link.role,
          }));

    const nextPrimaryContactId =
      dto.primaryContactId !== undefined
        ? dto.primaryContactId
        : dto.contactId !== undefined
          ? dto.contactId
          : currentDeal.primaryContactId;

    await this.assertValidDealContactLinks(
      nextContactLinks,
      nextPrimaryContactId ?? null,
      resolvedCompanyId,
    );

    await this.dataSource.transaction(async (manager) => {
      const dealRepo = manager.getRepository(DealEntity);
      const dealContactRepo = manager.getRepository(DealContactEntity);

      const mergedDeal = dealRepo.merge(currentDeal, {
        name: dto.name ?? currentDeal.name,
        value: dto.value === undefined ? currentDeal.value : dto.value.toFixed(2),
        stage: dto.stage ?? currentDeal.stage,
        companyId: resolvedCompanyId,
        primaryContactId: nextPrimaryContactId ?? null,
        expectedCloseDate:
          dto.expectedCloseDate === undefined
            ? currentDeal.expectedCloseDate
            : dto.expectedCloseDate,
      });

      await dealRepo.save(mergedDeal);

      if (dto.contactLinks !== undefined || dto.contactId !== undefined) {
        await dealContactRepo.delete({ dealId: id });

        if (nextContactLinks.length > 0) {
          await dealContactRepo.save(
            nextContactLinks.map((link) =>
              dealContactRepo.create({
                dealId: id,
                contactId: link.contactId,
                role: link.role ?? null,
              }),
            ),
          );
        }
      }
    });

    return this.getDealWithCompany(id);
  }

  async removeDeal(id: string): Promise<void> {
    await this.getDealById(id);
    await this.dealRepository.softDelete(id);
  }

  private normalizeContactLinks(
    contactLinks?: DealContactLinkDto[],
    legacyContactId?: string | null,
  ) {
    if (contactLinks !== undefined) {
      const deduped = new Map<string, DealContactLinkDto>();

      for (const link of contactLinks) {
        deduped.set(link.contactId, {
          contactId: link.contactId,
          role: link.role?.trim() || null,
        });
      }

      return Array.from(deduped.values());
    }

    if (legacyContactId) {
      return [{ contactId: legacyContactId, role: null }];
    }

    return [];
  }

  private async assertValidDealContactLinks(
    contactLinks: Array<{ contactId: string; role?: string | null }>,
    primaryContactId: string | null,
    companyId: string,
  ) {
    const contactIds = contactLinks.map((link) => link.contactId);

    await this.contactService.assertContactsExist(contactIds);
    await this.contactService.assertContactsLinkedToCompany(contactIds, companyId);

    if (
      primaryContactId &&
      !contactIds.includes(primaryContactId)
    ) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: '"'Primary contact must be included in contactLinks.',
        details: {
          errors: [
            {
              field: 'primaryContactId',
              messages: ['Primary contact must be included in contactLinks.'],
            },
          ],
        },
      });
    }
  }

  private async assertCompanyExists(companyId: string) {
    try {
      await this.companyService.getCompanyById(companyId);
    } catch (error) {
      if ("'!(error instanceof HttpException) || error.getStatus() !== 404) {
        throw error;
      }

      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
        message: `Company with ID ${companyId} not found`,
        details: {
          resource: '"'Company',
          id: companyId,
        },
      });
    }
  }

  private async getDealContactLinks(dealId: string) {
    return this.dataSource.getRepository(DealContactEntity).find({
      where: { dealId },
    });
  }

  private async hydrateSingleDeal(deal: DealEntity): Promise<HydratedDeal> {
    const [hydrated] = await this.hydrateDeals([deal]);
    return hydrated;
  }

  private async hydrateDeals(deals: DealEntity[]): Promise<HydratedDeal[]> {
    if (deals.length === 0) {
      return [];
    }

    const dealIds = deals.map((deal) => deal.id);
    const companyIds = Array.from(new Set(deals.map((deal) => deal.companyId)));

    const companies = await this.dataSource
      .getRepository(CompanyEntity)
      .findByIds(companyIds);

    const companyById = new Map(companies.map((company) => [company.id, company]));

    const contactRows = await this.dealRepository.getContactRowsForDeals(dealIds);
    const contactsByDealId = new Map<
      string,
      Array<{ id: string; name: string; role: string | null }>
    >();

    for (const row of contactRows) {
      const current = contactsByDealId.get(row.dealId) ?? [];
      current.push({
        id: row.contactId,
        name: row.contactName,
        role: row.role,
      });
      contactsByDealId.set(row.dealId, current);
    }

    return deals.map((deal) => {
      const company = companyById.get(deal.companyId);
      const contacts = (contactsByDealId.get(deal.id) ?? []).map((contact) => ({
        ...contact,
        primary: deal.primaryContactId === contact.id,
      }));

      contacts.sort((a, b) => Number(b.primary) - Number(a.primary));

      return {
        ...deal,
        company: {
          id: company?.id ?? deal.companyId,
          name: company?.name ?? deal.companyId,
          status: company?.status ?? '0',
        },
        contacts,
      };
    });
  }
}
