    if (legacyContactId) {
      return [{ contactId: legacyContactId, role: null }];
    }

    return [];
  }

  private async assertValidDealContactLinks(
    contactLinks: Array<{ contactId: string; role?: string | null }>,
    primaryContactId: string | null,
    companyId: string,
  ) {
    const contactIds = contactLinks.map((link) => link.contactId);

    await this.contactService.assertContactsExist(contactIds);
    await this.contactService.assertContactsLinkedToCompany(contactIds, companyId);

    if (
      primaryContactId &&
      !contactIds.includes(primaryContactId)
    ) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: '"'Primary contact must be included in contactLinks.',
        details: {
          errors: [
            {
              field: 'primaryContactId',
              messages: ['Primary contact must be included in contactLinks.'],
            },
          ],
        },
      });
    }
  }

  private async assertCompanyExists(companyId: string) {
    try {
      await this.companyService.getCompanyById(companyId);
    } catch (error) {
      if ("'!(error instanceof HttpException) || error.getStatus() !== 404) {
        throw error;
      }

      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
        message: `Company with ID ${companyId} not found`,
        details: {
          resource: '"'Company',
          id: companyId,
        },
      });
    }
  }

  private async getDealContactLinks(dealId: string) {
    return this.dataSource.getRepository(DealContactEntity).find({
      where: { dealId },
    });
  }

  private async hydrateSingleDeal(deal: DealEntity): Promise<HydratedDeal> {
    const [hydrated] = await this.hydrateDeals([deal]);
    return hydrated;
  }

  private async hydrateDeals(deals: DealEntity[]): Promise<HydratedDeal[]> {
    if (deals.length === 0) {
      return [];
    }

    const dealIds = deals.map((deal) => deal.id);
    const companyIds = Array.from(new Set(deals.map((deal) => deal.companyId)));

    const companies = await this.dataSource
      .getRepository(CompanyEntity)
      .findByIds(companyIds);

    const companyById = new Map(companies.map((company) => [company.id, company]));

    const contactRows = await this.dealRepository.getContactRowsForDeals(dealIds);
    const contactsByDealId = new Map<
      string,
      Array<{ id: string; name: string; role: string | null }>
    >();

    for (const row of contactRows) {
      const current = contactsByDealId.get(row.dealId) ?? [];
      current.push({
        id: row.contactId,
        name: row.contactName,
        role: row.role,
      });
      contactsByDealId.set(row.dealId, current);
    }

    return deals.map((deal) => {
      const company = companyById.get(deal.companyId);
      const contacts = (contactsByDealId.get(deal.id) ?? []).map((contact) => ({
        ...contact,
        primary: deal.primaryContactId === contact.id,
      }));

      contacts.sort((a, b) => Number(b.primary) - Number(a.primary));

      return {
        ...deal,
        company: {
          id: company?.id ?? deal.companyId,
          name: company?.name ?? deal.companyId,
          status: company?.status ?? '0',
        },
        contacts,
      };
    });
  }
}
