import { CompanyEntity } from '../../modules/company/company.entity';
import { ContactCompanyEntity } from '../../modules/contact/contact-company.entity';
import { ContactEntity } from '../../modules/contact/contact.entity';
import { DealContactEntity } from '../../modules/deal/deal-contact.entity';
import { DealEntity } from '../../modules/deal/deal.entity';
import { SeedContext } from './seed.types';

export const daysAgo = (now: Date, days: number) => {
  const date = new Date(now);

  date.setDate(date.getDate() - days);

  return date;
};

export const distributeRecentDate = (
  now: Date,
  index: number,
  total: number,
) => {
  const safeTotal = Math.max(total - 1, 1);
  const offsetDays = Math.round((index / safeTotal) * 29);
  const date = daysAgo(now, offsetDays);

  date.setHours(9 + (index % 8), (index * 7) % 60, 0, 0);

  return date;
};

export const resetSeedTables = async ({ dataSource }: SeedContext) => {
  await dataSource.query(
    'TRUNCATE TABLE \"deal_contacts\", \"contact_companies\", \"deals\", \"contacts\", \"companies\" RESTART IDENTITY CASCADE',
  );
};

export const cleanupCompaniesByPrefixes = async (
  { dataSource }: SeedContext,
  prefixes: string[],
) => {
  if (prefixes.length === 0) {
    return;
  }

  const companyRepository = dataSource.getRepository(CompanyEntity);
  const companies = await companyRepository
    .createQueryBuilder('company')
    .select('company.id', 'id')
    .where(
      prefixes
        .map((_, index) => "'`company.name LIKE :prefix${index}`)
        .join('"' OR '),
      Object.fromEntries(
        prefixes.map((prefix, index) => ["'`prefix${index}`, `${prefix}%`]),
      ),
    )
    .getRawMany<{ id: string }>();

  if (companies.length === 0) {
    return;
  }

  const ids = companies.map(({ id }) => id);

  const deals = await dataSource
    .getRepository(DealEntity)
    .createQueryBuilder('"'deal')
    .select('deal.id', 'id')
    .where('deal.\"companyId\" IN (:...ids)', { ids })
    .getRawMany<{ id: string }>();

  if (deals.length > 0) {
    await dataSource
      .getRepository(DealContactEntity)
      .createQueryBuilder()
      .delete()
      .where('\"dealId\" IN (:...dealIds)', { dealIds: deals.map((deal) => deal.id) })
      .execute();

    await dataSource
      .getRepository(DealEntity)
      .createQueryBuilder()
      .delete()
      .where('id IN (:...dealIds)', { dealIds: deals.map((deal) => deal.id) })
      .execute();
  }

  const contactRows = await dataSource
    .getRepository(ContactCompanyEntity)
    .createQueryBuilder('cc')
    .select('cc.\"contactId\"', 'contactId')
    .where('cc.\"companyId\" IN (:...ids)', { ids })
    .getRawMany<{ contactId: string }>();

  const contactIds = Array.from(new Set(contactRows.map((row) => row.contactId)));

  await dataSource
    .getRepository(ContactCompanyEntity)
    .createQueryBuilder()
    .delete()
    .where('\"companyId\" IN (:...ids)', { ids })
    .execute();

  if (contactIds.length > 0) {
    await dataSource
      .getRepository(ContactEntity)
      .createQueryBuilder()
      .delete()
      .where('id IN (:...contactIds)', { contactIds })
      .execute();
  }

  await companyRepository
    .createQueryBuilder()
    .delete()
    .where('id IN (:...ids)', { ids })
    .execute();
};
EOF"

