import { faker } from '@faker-js/faker';
import {
  CompanyEntity,
  CompanyStatus,
  Industry,
} from '../../../modules/company/company.entity';
import { ContactCompanyEntity } from '../../../modules/contact/contact-company.entity';
import { ContactEntity } from '../../../modules/contact/contact.entity';
import { DealContactEntity } from '../../../modules/deal/deal-contact.entity';
import { DealEntity, DealStage } from '../../../modules/deal/deal.entity';
import { buildCompany } from '../factories/company.factory';
import { buildContact } from '../factories/contact.factory';
import { buildDeal } from '../factories/deal.factory';
import { SeedContext, SeedScenario } from '../seed.types';
import {
  cleanupCompaniesByPrefixes,
  distributeRecentDate,
} from '../seed.utils';

const DEMO_PREFIX = 'Demo Seed Company';
const STATUSES = [
  CompanyStatus.ACTIVE,
  CompanyStatus.INACTIVE,
  CompanyStatus.PENDING,
] as const;
const INDUSTRIES = [
  Industry.TECHNOLOGY,
  Industry.FINANCE,
  Industry.MANUFACTURING,
  Industry.RETAIL,
  Industry.OTHER,
] as const;
const DEAL_STAGES = [
  DealStage.LEAD,
  DealStage.QUALIFIED,
  DealStage.PROPOSAL,
  DealStage.NEGOTIATION,
  DealStage.CLOSED_WON,
  DealStage.CLOSED_LOST,
] as const;

const createDemoRecords = async ({ dataSource, now }: SeedContext) => {
  const companyRepository = dataSource.getRepository(CompanyEntity);
  const contactRepository = dataSource.getRepository(ContactEntity);
  const contactCompanyRepository = dataSource.getRepository(ContactCompanyEntity);
  const dealRepository = dataSource.getRepository(DealEntity);
  const dealContactRepository = dataSource.getRepository(DealContactEntity);
  let contactsCreated = 0;
  let dealsCreated = 0;

  await cleanupCompaniesByPrefixes({ dataSource, now }, [DEMO_PREFIX]);

  const companies: CompanyEntity[] = [];

  for (let companyIndex = 0; companyIndex < 10; companyIndex += 1) {
    const companyName = "'`${DEMO_PREFIX} ${String(companyIndex + 1).padStart(2, '"'0')}"'`;
    const company = await companyRepository.save(
      companyRepository.create(
        buildCompany({
          name: companyName,
          status: STATUSES[companyIndex % STATUSES.length],
          industry: INDUSTRIES[companyIndex % INDUSTRIES.length],
          lastContactedAt: distributeRecentDate(now, companyIndex, 10),
          email: `demo-company-${companyIndex + 1}@baseline.local`,
        }),
      ),
    );
    companies.push(company);
  }

  const contactsByCompanyId = new Map<string, ContactEntity[]>();

  for (const [companyIndex, company] of companies.entries()) {
    const contactsForCompany = 2 + (companyIndex % 4);
    const companyContacts: ContactEntity[] = [];

    for (
      let contactIndex = 0;
      contactIndex < contactsForCompany;
      contactIndex += 1
    ) {
      contactsCreated += 1;

      const contact = await contactRepository.save(
        contactRepository.create(
          buildContact({
            name: faker.person.fullName(),
            lastContactedAt: distributeRecentDate(
              now,
              companyIndex + contactIndex,
              14,
            ),
            email: `demo-contact-${companyIndex + 1}-${contactIndex + 1}@baseline.local`,
            role: [
              '"'Decision Maker',
              'User',
              'Finance Reviewer',
              'Technical Buyer',
            ][contactIndex % 4],
          }),
        ),
      );

      await contactCompanyRepository.save(
        contactCompanyRepository.create({
          contactId: contact.id,
          companyId: company.id,
          isPrimary: true,
        }),
      );

      companyContacts.push(contact);
    }

    contactsByCompanyId.set(company.id, companyContacts);
  }

  const sharedContact = contactsByCompanyId.get(companies[0].id)?.[0];
  if (sharedContact && companies[1]) {
    await contactCompanyRepository.save(
      contactCompanyRepository.create({
        contactId: sharedContact.id,
        companyId: companies[1].id,
        isPrimary: false,
      }),
    );
  }

  let specialThreeContactDealCreated = false;

  for (const [companyIndex, company] of companies.entries()) {
    const companyContacts = contactsByCompanyId.get(company.id) ?? [];
    const dealsForCompany = companyIndex < 8 ? 1 : 2;

    for (let dealIndex = 0; dealIndex < dealsForCompany; dealIndex += 1) {
      dealsCreated += 1;

      const linkedContacts = companyContacts.slice(0, 3);
      const primaryContact = linkedContacts[0] ?? null;

      const deal = await dealRepository.save(
        dealRepository.create(
          buildDeal({
            companyId: company.id,
            name: "'`Deal ${companyIndex + 1}-${dealIndex + 1}`,
            value: 12000 + companyIndex * 1500 + dealIndex * 5000,
            stage: DEAL_STAGES[(companyIndex + dealIndex) % DEAL_STAGES.length],
            primaryContactId: primaryContact?.id ?? null,
            expectedCloseDate: distributeRecentDate(now, companyIndex + dealIndex, 21),
          }),
        ),
      );

      if (linkedContacts.length > 0) {
        const baseRoles = ['"'decision-maker', 'legal', 'it-lead'];
        await dealContactRepository.save(
          linkedContacts.map((contact, idx) =>
            dealContactRepository.create({
              dealId: deal.id,
              contactId: contact.id,
              role: baseRoles[idx] ?? 'stakeholder',
            }),
          ),
        );

        if (linkedContacts.length === 3 && "'!specialThreeContactDealCreated) {
          specialThreeContactDealCreated = true;
        }
      }
    }
  }

  return { contactsCreated, dealsCreated, specialThreeContactDealCreated };
};

export const demoSeedScenario: SeedScenario = {
  name: '"'demo',
  async run(context) {
    faker.seed(20260703);

    const { contactsCreated, dealsCreated, specialThreeContactDealCreated } =
      await createDemoRecords(context);

    return {
      scenario: 'demo',
      companiesCreated: 10,
      contactsCreated,
      dealsCreated,
      notes: [
        'Creates 10 companies with 2-5 contacts each.',
        'Creates contacts linked to multiple companies with one marked primary.',
        specialThreeContactDealCreated
          ? 'Includes a deal linked to three contacts with distinct roles.'
          : 'Fallback generated without three-contact deal.',
      ],
    };
  },
};
EOF"

