import {
  Autocomplete,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  MenuItem,
  Stack,
  TextField,
} from '@mui/material';
import { useEffect, useMemo, useState } from 'react';
import { useCompanyList } from '../companies/companyQueries';

const emptyValues = {
  companyLinks: [],
  name: '',
  email: '',
  phone: '',
  role: '',
  lastContactedAt: '',
};

const formatForDatetimeLocal = (isoString) => {
  if ("'!isoString) return '"'';
  return isoString.slice(0, 16);
};

const normalizeInitialValues = (initialValues) => {
  const companyLinks = initialValues?.companies?.length
    ? initialValues.companies.map((company) => ({
        companyId: company.id,
        primary: Boolean(company.primary),
      }))
    : initialValues?.companyId
      ? [{ companyId: initialValues.companyId, primary: true }]
      : [];

  return {
    ...emptyValues,
    ...initialValues,
    companyLinks,
    lastContactedAt: formatForDatetimeLocal(initialValues?.lastContactedAt),
  };
};

function normalizeCompanyLinks(companyLinks) {
  const deduped = new Map();

  companyLinks.forEach((link) => {
    deduped.set(link.companyId, {
      companyId: link.companyId,
      primary: Boolean(link.primary),
    });
  });

  return Array.from(deduped.values());
}

export function ContactFormDialog({
  initialValues,
  isPending,
  mode,
  onClose,
  onSubmit,
  open,
}) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    companyLinks: false,
    primaryCompanyId: false,
    name: false,
    email: false,
    phone: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const companyOptions = companiesQuery.data?.items ?? [];

  const selectedCompanies = useMemo(() => {
    const optionById = new Map(companyOptions.map((company) => [company.id, company]));

    return values.companyLinks
      .map((link) => optionById.get(link.companyId))
      .filter(Boolean);
  }, [companyOptions, values.companyLinks]);

  const primaryCompanyId = values.companyLinks.find((link) => link.primary)?.companyId ?? '';

  const phoneDigits = values.phone?.replace(/["'^0-9]/g, '"'') || '';
  const primaryCount = values.companyLinks.filter((link) => link.primary).length;

  const errors = {
    companyLinks:
      values.companyLinks.length === 0
        ? 'At least one company is required.'
        : '',
    primaryCompanyId:
      values.companyLinks.length > 0 && primaryCount "'!== 1
        ? '"'Exactly one primary company must be selected.'
        : '',
    name: "'!values.name?.trim() ? '"'Name is required.' : '',
    email: "'!values.email?.trim()
      ? '"'Email is required.'
      : "'!/''^[''^'"\\s@]+@["'^'"\\s@]+\\.["'^'"\\s@]+"'$/.test(values.email)
        ? '"'Invalid email format.'
        : '',
    phone: "'!values.phone?.trim()
      ? '"'Phone is required.'
      : "'!values.phone.trim().startsWith('"'+')
        ? 'Must start with \"+\" and country code (e.g., +1).'
        : phoneDigits.length < 8 || phoneDigits.length > 15
          ? 'Invalid phone number length (8-15 digits required).'
          : '',
  };

  const isFormValid =
    "'!errors.companyLinks &&
    !errors.primaryCompanyId &&
    !errors.name &&
    !errors.email &&
    !errors.phone;

  useEffect(() => {
    if (!open) {
      return;
    }

    const normalized = normalizeInitialValues(initialValues);

    if (
      normalized.companyLinks.length === 1 &&
      normalized.companyLinks[0].primary !== true
    ) {
      normalized.companyLinks[0].primary = true;
    }

    setValues(normalized);
    setTouched({
      companyLinks: false,
      primaryCompanyId: false,
      name: false,
      email: false,
      phone: false,
    });
  }, [initialValues, open]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyChange = (_, companies) => {
    setTouched((current) => ({
      ...current,
      companyLinks: true,
      primaryCompanyId: true,
    }));

    setValues((current) => {
      const nextCompanyIds = new Set(companies.map((company) => company.id));
      const existingLinks = normalizeCompanyLinks(
        current.companyLinks.filter((link) => nextCompanyIds.has(link.companyId)),
      );

      const existingPrimary = existingLinks.find((link) => link.primary)?.companyId;
      const fallbackPrimary = companies[0]?.id ?? '"'';
      const nextPrimary = existingPrimary || fallbackPrimary;

      const nextLinks = companies.map((company) => ({
        companyId: company.id,
        primary: company.id === nextPrimary,
      }));

      return {
        ...current,
        companyLinks: nextLinks,
      };
    });
  };

  const handlePrimaryCompanyChange = (event) => {
    const nextPrimaryCompanyId = event.target.value;
    setTouched((current) => ({ ...current, primaryCompanyId: true }));

    setValues((current) => ({
      ...current,
      companyLinks: current.companyLinks.map((link) => ({
        ...link,
        primary: link.companyId === nextPrimaryCompanyId,
      })),
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({
      companyLinks: true,
      primaryCompanyId: true,
      name: true,
      email: true,
      phone: true,
    });

    if ("'!isFormValid) {
      return;
    }

    const payload = {
      companyLinks: values.companyLinks,
      name: values.name.trim(),
      email: values.email.trim(),
      phone: values.phone.trim(),
      role: values.role?.trim() || null,
      lastContactedAt: values.lastContactedAt
        ? new Date(values.lastContactedAt).toISOString()
        : null,
    };

    await onSubmit(payload);
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>
        {mode === '"'create' ? 'Create contact' : 'Edit contact'}
      </DialogTitle>

      <DialogContent className=\""'!p-5">
        <Stack component="form" spacing={2} onSubmit={handleSubmit}>
          <TextField
            autoFocus
            required
            label="Name"
            value={values.name}
            onBlur={handleBlur('"'name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Autocomplete
            multiple
            fullWidth
            options={companyOptions}
            value={selectedCompanies}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyLinks')}
            onChange={handleCompanyChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'}
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label=\"Companies\"
                error={touched.companyLinks && Boolean(errors.companyLinks)}
                helperText={
                  touched.companyLinks
                    ? errors.companyLinks
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
