      dataSource as any,
    );

    return {
      service,
      dealRepository,
      companyService,
      contactService,
      dataSource,
      dealRepoInTx,
      dealContactRepoInTx,
      companyRepo,
    };
  };

  it('creates a deal with contact links and primary contact', async () => {
    const {
      service,
      companyService,
      contactService,
      dealRepository,
      companyRepo,
    } = buildService();

    companyService.getCompanyById.mockResolvedValue({ id: 'company-1' });
    contactService.assertContactsExist.mockResolvedValue(undefined);
    contactService.assertContactsLinkedToCompany.mockResolvedValue(undefined);
    dealRepository.getContactRowsForDeals.mockResolvedValue([
      {
        dealId: 'deal-1',
        contactId: 'contact-1',
        role: 'decision-maker',
        contactName: 'Alice',
      },
    ]);
    companyRepo.find.mockResolvedValue([
      { id: 'company-1', name: 'Acme', status: '1' },
    ]);

    const created = await service.createDeal({
      name: 'Pilot Expansion',
      value: 12500,
      companyId: 'company-1',
      contactLinks: [{ contactId: 'contact-1', role: 'decision-maker' }],
      primaryContactId: 'contact-1',
    });

    expect(created.stage).toBe(DealStage.LEAD);
    expect(created.primaryContactId).toBe('contact-1');
    expect(Number(created.value)).toBe(12500);
    expect(created.contacts[0]).toMatchObject({
      id: 'contact-1',
      primary: true,
      role: 'decision-maker',
    });
  });

  it('allows deals with zero linked contacts', async () => {
    const { service, companyService, dealRepository, companyRepo } = buildService();

    companyService.getCompanyById.mockResolvedValue({ id: 'company-1' });
    dealRepository.getContactRowsForDeals.mockResolvedValue([]);
    companyRepo.find.mockResolvedValue([{ id: 'company-1', name: 'Acme', status: '1' }]);

    const created = await service.createDeal({
      name: 'Zero Contacts',
      value: 100,
      companyId: 'company-1',
      contactLinks: [],
      primaryContactId: null,
    });

    expect(created.contacts).toEqual([]);
    expect(created.primaryContactId).toBeNull();
  });

  it('returns validation error when primary contact is not linked', async () => {
    const { service, companyService, contactService } = buildService();

    companyService.getCompanyById.mockResolvedValue({ id: 'company-1' });
    contactService.assertContactsExist.mockResolvedValue(undefined);
    contactService.assertContactsLinkedToCompany.mockResolvedValue(undefined);

    await expect(
      service.createDeal({
        name: 'Invalid Primary',
        value: 300,
        companyId: 'company-1',
        contactLinks: [{ contactId: 'contact-1' }],
        primaryContactId: 'contact-2',
      }),
    ).rejects.toMatchObject({
      status: HttpStatus.BAD_REQUEST,
      response: {
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
      },
    });
  });

  it('propagates not-found when replacing with unknown contacts', async () => {
    const { service, dealRepository, companyService, contactService } = buildService();

    dealRepository.findOne.mockResolvedValue({
      id: 'deal-1',
      name: 'Deal',
      value: '100.00',
      stage: DealStage.LEAD,
      companyId: 'company-1',
      primaryContactId: null,
      expectedCloseDate: null,
    });

    companyService.getCompanyById.mockResolvedValue({ id: 'company-1' });
    contactService.assertContactsExist.mockRejectedValue(
      new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.NOT_FOUND,
        message: 'Contact missing',
      }),
    );

    await expect(
      service.updateDeal('deal-1', {
        contactLinks: [{ contactId: 'missing-contact' }],
      }),
    ).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.NOT_FOUND,
      },
    });
  });

  it('returns paginated list from repository with stage/company filters', async () => {
    const { service, dealRepository } = buildService();

    const expected = {
      items: [{ id: 'deal-1', companyId: 'company-1', primaryContactId: null }],
      total: 1,
      page: 1,
      pageSize: 10,
      totalPages: 1,
    };

    dealRepository.findWithFilter.mockResolvedValue(expected);
    dealRepository.getContactRowsForDeals.mockResolvedValue([]);

    const result = await service.getDealsList({
      page: 1,
      pageSize: 10,
      stage: 'proposal',
      companyId: 'company-1',
    });

    expect(dealRepository.findWithFilter).toHaveBeenCalledWith({
      page: 1,
      pageSize: 10,
      stage: 'proposal',
      companyId: 'company-1',
    });
    expect(result.total).toBe(1);
  });
});
